#include <cstddef>
#include <functional>

void* my_memmove(void* dst, const void* src, std::size_t n) {
  auto* d = static_cast<unsigned char*>(dst);
  auto* s = static_cast<const unsigned char*>(src);
  if (d == s || n == 0) return dst;
  if (std::less<const unsigned char*>{}(d, s)) {
    // dst before src: forward copy never overwrites unread bytes
    for (std::size_t i = 0; i < n; ++i) d[i] = s[i];
  } else {
    // dst after src: copy backward
    for (std::size_t i = n; i-- > 0;) d[i] = s[i];
  }
  return dst;
}
